// @ts-ignore
import { default as openNextHandler } from './.open-next/worker.js'
import { purgeExpiredChatData } from './lib/chat/repository'
import { CHAT_LIMITS } from './lib/chat/limits'
import { handleRealtimeRequest } from './lib/chat/realtime-http'
import { isScannerPath } from './lib/scanner-path'

const MAX_PURGE_BATCHES_PER_RUN = 10
const MUSIC_MEDIA_PATH = /^\/media\/music\/[A-Za-z0-9._/-]+$/
const GALLERY_VIDEO_PATH = /^\/media\/(?:gaming|gallery-phase2)\/[A-Za-z0-9._/-]+\.mp4$/
const GALLERY_MEDIA_BASE_URL = 'https://media.solidays.win'

async function proxyGalleryVideo(request: Request) {
  const url = new URL(request.url)

  if (request.method !== 'GET' && request.method !== 'HEAD') {
    return null
  }

  if (!GALLERY_VIDEO_PATH.test(url.pathname)) return null

  const headers = new Headers()
  for (const name of ['range', 'if-range', 'if-none-match', 'if-modified-since']) {
    const value = request.headers.get(name)
    if (value) headers.set(name, value)
  }

  const upstreamUrl = `${GALLERY_MEDIA_BASE_URL}/${url.pathname.slice('/media/'.length)}${url.search}`
  const response = await fetch(upstreamUrl, {
    method: request.method,
    headers,
  })

  // Return the upstream ranged response directly. The upstream Content-Length
  // is important to Chromium's media loader and must not be lost in the
  // OpenNext Node response adapter.
  return response
}

function createFixedLengthBody(body: ReadableStream<Uint8Array>, size: number) {
  const fixedLength = new FixedLengthStream(size)
  void body.pipeTo(fixedLength.writable).catch((error) => {
    void fixedLength.writable.abort(error)
  })
  return fixedLength.readable
}

async function preserveMusicContentLength(
  request: Request,
  env: CloudflareEnv,
  response: Response
) {
  const pathname = new URL(request.url).pathname

  if (
    request.method !== 'GET' ||
    response.status !== 200 ||
    !MUSIC_MEDIA_PATH.test(pathname) ||
    response.headers.has('content-length') ||
    !response.body
  ) {
    return response
  }

  const key = pathname.slice('/media/'.length)
  const object = await env.MEDIA_BUCKET.head(key)
  if (!object) return response

  const headers = new Headers(response.headers)
  headers.set('content-length', String(object.size))
  headers.set('accept-ranges', 'bytes')

  return new Response(createFixedLengthBody(response.body, object.size), {
    status: response.status,
    statusText: response.statusText,
    headers,
  })
}

function isExplicitlyCacheable(request: Request, response: Response) {
  const url = new URL(request.url)
  const contentType = response.headers.get('content-type') ?? ''
  const isImage = contentType.toLowerCase().startsWith('image/')
  const isMusic =
    url.pathname.startsWith('/media/music/') && contentType.toLowerCase().startsWith('audio/')
  const hasMusicContentLength = !isMusic || response.headers.has('content-length')

  return (
    (request.method === 'GET' || request.method === 'HEAD') &&
    url.pathname.startsWith('/media/') &&
    response.status === 200 &&
    (isImage || isMusic) &&
    hasMusicContentLength &&
    !response.headers.has('set-cookie')
  )
}

export default {
  async fetch(request: Request, env: CloudflareEnv, ctx: ExecutionContext) {
    const url = new URL(request.url)

    if (isScannerPath(url.pathname)) {
      return new Response('Not found', {
        status: 404,
        headers: {
          'Cache-Control': 'no-store',
          'Content-Type': 'text/plain; charset=utf-8',
          'X-Content-Type-Options': 'nosniff',
        },
      })
    }

    const galleryVideoResponse = await proxyGalleryVideo(request)
    if (galleryVideoResponse) return galleryVideoResponse

    // OpenNext's Node response adapter cannot construct a 101 upgrade. Route
    // realtime requests directly so the platform WebSocket handle survives.
    const realtimeResponse = await handleRealtimeRequest(request, env)
    if (realtimeResponse) return realtimeResponse

    const response = await openNextHandler.fetch(request, env, ctx)

    let normalizedResponse = response
    if (
      response.status === 200 &&
      response.headers.get('content-type')?.toLowerCase().startsWith('audio/')
    ) {
      try {
        normalizedResponse = await preserveMusicContentLength(request, env, response)
      } catch {
        // The audio response is still usable without cache range metadata.
      }
    }

    // A WebSocket upgrade response must keep its platform WebSocket handle.
    // Re-wrapping it below would turn the 101 into a normal Response and drop
    // the connection before it reaches the browser.
    if (normalizedResponse.webSocket) {
      return normalizedResponse
    }

    if (isExplicitlyCacheable(request, normalizedResponse)) {
      return normalizedResponse
    }

    const headers = new Headers(normalizedResponse.headers)
    headers.set('Cache-Control', 'private, no-store, max-age=0')
    headers.set('CDN-Cache-Control', 'no-store')
    headers.set('Cloudflare-CDN-Cache-Control', 'no-store')

    return new Response(normalizedResponse.body, {
      status: normalizedResponse.status,
      statusText: normalizedResponse.statusText,
      headers,
    })
  },

  async scheduled(controller: ScheduledController, env: CloudflareEnv) {
    if (controller.cron !== CHAT_LIMITS.cleanupCron) return

    for (let batch = 0; batch < MAX_PURGE_BATCHES_PER_RUN; batch += 1) {
      const result = await purgeExpiredChatData(env.CHAT_DB)
      if (result.conversations < CHAT_LIMITS.purgeBatchSize) break
    }
  },
} satisfies ExportedHandler<CloudflareEnv>

